// RETIRED: lead_followups_due() (migration 035) now sends each owner one
// in-app daily digest, with push. This workflow stays in git, inactive, so it
// can come back as an email channel without a rebuild; automation_jobs marks
// it paused. If it is ever switched on it mails each owner only their own
// leads, and unowned leads (or an owner who left) to the admins.
//
// Three buckets that kill conversion:
//   1. never replied to      → speed-to-lead failure
//   2. follow-up date passed → a promise you broke
//   3. untouched N+ days     → going cold
const MNL = 'Asia/Manila';
const EMAIL_RE = /^[^\s@,;<>"']+@[^\s@,;<>"']+\.[^\s@,;<>"']+$/;
const rowsOf = (name) => $(name).all().map(i => i.json).flat().filter(r => r && typeof r === 'object');
// workspace_settings is a singleton keyed by id = true (migration 033); the
// stale threshold is the one admins set in Settings → Growth.
const settings = rowsOf('Settings').find(r => r.id === true) || {};
const STALE_DAYS = Number.isInteger(settings.growth_stale_days) && settings.growth_stale_days > 0 ? settings.growth_stale_days : 14;
const people = rowsOf('Recipients')
  .filter(p => p.id && !p.deactivated_at && EMAIL_RE.test(String(p.email || '').trim()));
const admins = people.filter(p => p.role === 'admin');

const rows = rowsOf('Fetch open leads').filter(r => r.id && r.spam !== true);
const now = Date.now();
const today = new Intl.DateTimeFormat('en-CA', { timeZone: MNL, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const days = (iso) => Math.floor((now - new Date(iso).getTime()) / 86400000);

// recipient address list → { noReply, overdue, cold }
const byTo = new Map();
const bucketFor = (lead) => {
  const owner = people.find(p => p.id === lead.owner_id);
  const list = owner ? [owner] : admins;
  const to = [...new Set(list.map(p => String(p.email).trim().toLowerCase()))].join(',');
  if (!to) return null;
  if (!byTo.has(to)) byTo.set(to, { noReply: [], overdue: [], cold: [] });
  return byTo.get(to);
};
for (const r of rows) {
  let bucket = null;
  let item = null;
  if (!r.first_responded_at) { bucket = 'noReply'; item = { ...r, age: days(r.created_at) }; }
  else if (r.follow_up && r.follow_up <= today) { bucket = 'overdue'; item = { ...r, age: days(r.last_touch_at || r.created_at) }; }
  else if (days(r.last_touch_at || r.created_at) >= STALE_DAYS) { bucket = 'cold'; item = { ...r, age: days(r.last_touch_at || r.created_at) }; }
  if (!bucket) continue;
  const b = bucketFor(r);
  if (b) b[bucket].push(item);
}

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const money = (n) => n ? ('$' + Number(n).toLocaleString('en-US')) : '';
const rowsHtml = (list, tone) => list.map(r => `<tr>
  <td style="padding:6px 12px;border-bottom:1px solid #eee">${esc(r.name)}${r.hot ? ' 🔥' : ''}</td>
  <td style="padding:6px 12px;border-bottom:1px solid #eee;color:#666">${esc(r.stage)}</td>
  <td style="padding:6px 12px;border-bottom:1px solid #eee;color:${tone};font-weight:600">${r.age}d</td>
  <td style="padding:6px 12px;border-bottom:1px solid #eee;color:#666">${money(r.value)}</td>
</tr>`).join('');
const block = (title, list, tone, why) => list.length ? `
  <h3 style="margin:20px 0 4px;font-size:14px">${title} (${list.length})</h3>
  <p style="margin:0 0 8px;color:#888;font-size:12px">${why}</p>
  <table style="border-collapse:collapse;font-size:14px;width:100%">${rowsHtml(list, tone)}</table>` : '';

const out = [];
for (const [to, b] of byTo) {
  const total = b.noReply.length + b.overdue.length + b.cold.length;
  if (!total) continue;
  const html = `<div style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#111">
  <h2 style="margin:0 0 4px">${total} lead${total === 1 ? '' : 's'} need you today</h2>
  <p style="margin:0 0 16px;color:#666">Most deals die from silence, not rejection.</p>
  ${block('Never replied to', b.noReply, '#dc2626', 'Speed is the single cheapest conversion lever — these have had no first response.')}
  ${block('Follow-up overdue', b.overdue, '#d97706', 'You set a follow-up date and it has passed.')}
  ${block('Going cold', b.cold, '#d97706', `No touch in ${STALE_DAYS}+ days.`)}
  <p style="margin-top:20px"><a href="https://workspace.nixgensolutions.com/growth/leads" style="background:#2563eb;color:#fff;text-decoration:none;padding:9px 14px;border-radius:8px;font-size:14px">Open CRM Leads</a></p>
  <p style="margin-top:20px;color:#999;font-size:12px">Sent by n8n</p></div>`;
  out.push({ json: { to, html, count: total } });
}
// Nothing to nag about: stay silent.
return out;
